using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SunkenCurseEffect", menuName = "Data/Battle/Effects/Cellarius/SunkenCurse Effect")]
public class SunkenCurseEffect : Effect
{
	[SerializeField]
	private Effect empowerEffect;

	[SerializeField]
	private DefaultEffectAction doomAction;

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedAtTheEndOfYourTurn(), doomAction.GetActionDescription(amount).LowercaseFirst().RemoveLast(), base.localizationManager.GetLocalizedDecreaseEffect(empowerEffect, amount).LowercaseFirst());
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitEffects>().DecreaseEffect(empowerEffect, amount);
		doomAction.CastTargetAmount(effectOwner, amount, null);
		return amount;
	}
}
